import test from 'node:test';import assert from 'node:assert/strict';
import * as old from './reference-feature-practice.mjs';
import * as next from '../src/feature-practice.mjs';
import {createPractice,placePractice,retryPractice} from '../src/practice.mjs';
import {placeRehearsal,revealRehearsal,submitRehearsal,advanceRehearsal} from '../src/transfer-rehearsal.mjs';
import {createFeatureRehearsal,reviewFeatureRehearsal,importFeatureRehearsal,featureRehearsalInput} from '../src/feature-rehearsal.mjs';
const comparison=()=>({schema:'skill-translator-feature-clearance/v1',assumption:'circular-features-with-independent-euclidean-placement-tolerances',source:{title:'Independent review control',provenance:'Authored numeric test only',source:{widthMm:100,heightMm:100,corners:[{x:0,y:0},{x:100,y:0},{x:100,y:100},{x:0,y:100}],retainedNote:'source custody'},landmarks:[20,40,70].map((x,i)=>({id:['a','b','c'][i],label:['A','B','C'][i],sourcePx:{x,y:50},kind:'fraction',toleranceMm:2}))},features:[{id:'a',radiusMm:5},{id:'b',radiusMm:7},{id:'c',radiusMm:3}],requiredGapMm:10,workpieces:[{widthMm:100,heightMm:100},{widthMm:200,heightMm:100}]});
test('sixty differential current and historical reviews preserve original feature-practice semantics',()=>{
 const c=comparison();let seed=418617;const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed;};
 for(let k=0;k<60;k++){const width=k%2?100:200;let p=createPractice(c.source,width,100);
  for(let round=0;round<3;round++){
   const count=1+random()%3;for(let i=0;i<count;i++)p=placePractice(c.source,width,100,p,['a','b','c'][i],{xMm:random()%(width*8)/8,yMm:random()%800/8});
   for(let selected=1;selected<=p.round;selected++){const a=old.createFeaturePractice(c,p,selected),b=next.createFeaturePractice(c,p,selected);assert.deepEqual(b,a);assert.deepEqual(next.reviewFeaturePractice(b),old.reviewFeaturePractice(a));}
   if(round<2)p=retryPractice(c.source,width,100,p);
  }
 }
});
test('feedback uses final submitted coordinates while every reveal retains its own earlier coordinates',()=>{
 const c=comparison();let s=featureRehearsalInput(c);s=placeRehearsal(s,'a',{xMm:20,yMm:50});s=revealRehearsal(s);s=placeRehearsal(s,'a',{xMm:22,yMm:50});s=placeRehearsal(s,'b',{xMm:38,yMm:50});s=revealRehearsal(s);
 const unsubmitted=reviewFeatureRehearsal(createFeatureRehearsal(c,s));assert.equal(unsubmitted.trials[0].assessment,null);assert.equal(unsubmitted.trials[1].assessment,null);
 s=placeRehearsal(s,'b',{xMm:39,yMm:50});s=submitRehearsal(s);const trial=reviewFeatureRehearsal(createFeatureRehearsal(c,s)).trials[0];
 assert.deepEqual(trial.reveals.map(r=>r.priorAttempts),[[{id:'a',xMm:20,yMm:50}],[{id:'a',xMm:22,yMm:50},{id:'b',xMm:38,yMm:50}]]);
 const ab=trial.assessment.pairs.find(p=>p.from==='a'&&p.to==='b');assert.equal(ab.observedGapMm,5);assert.equal(ab.status,'fails');assert.equal(trial.assessment.pairs.find(p=>p.to==='c').status,'incomplete');
});
test('raw saved outcome and assistance claims cannot override admitted event history',()=>{
 const c=comparison();let s=featureRehearsalInput(c);s=submitRehearsal(s);s=advanceRehearsal(s);
 const b=createFeatureRehearsal(c,s,2),expected=reviewFeatureRehearsal(b),forged=structuredClone(b);
 forged.result={passed:true};forged.trials=[{assessment:{meetsAll:true}}];forged.rehearsal.trials=[{submitted:true,assistance:'none'}];forged.rehearsal.result={passed:true};forged.rehearsal.events[0].result={passed:true};
 assert.deepEqual(reviewFeatureRehearsal(forged),expected);assert.deepEqual(importFeatureRehearsal(forged),b);assert.equal(expected.trials[1].assessment,null);
});
test('ordered full-plan and complete annotation custody bind even metadata not used by geometry',()=>{
 const c=comparison(),s=featureRehearsalInput(c);
 for(const change of [x=>x.source.source.retainedNote='different',x=>x.source.landmarks.reverse(),x=>x.source.landmarks[0].label='changed',x=>x.source.landmarks[0].toleranceMm=3,x=>x.workpieces.reverse(),x=>x.workpieces.push({widthMm:150,heightMm:100})]){const other=structuredClone(c);change(other);assert.throws(()=>createFeatureRehearsal(other,s));}
 const reordered=Object.fromEntries(Object.entries(c).reverse());assert.deepEqual(createFeatureRehearsal(reordered,s),createFeatureRehearsal(c,s));
});

